//! Encoding tests with expected bytes generated by nasm 3.02 (the
//! reference submodule) and checked in, so the suite runs without nasm.

fn text_bytes(src: &str) -> Vec<u8> {
    let stmts = glasm::parse::parse_module(src).expect("parse");
    let module = glasm::assemble::assemble(&stmts).expect("assemble");
    module
        .sections
        .iter()
        .find(|s| s.name == ".text")
        .expect(".text")
        .data
        .clone()
}

fn check(src: &str, expected_hex: &str) {
    let got: String = text_bytes(src).iter().map(|b| format!("{b:02x}")).collect();
    assert_eq!(got, expected_hex);
}

#[test]
fn core_integer_forms() {
    // Generated by: nasm -f elf64 with the same source.
    check(
        r"
        bits 64
        mov rax, rbx
        mov rax, 5
        mov eax, 5
        mov al, 5
        mov rax, 0x123456789
        add rax, rbx
        add rax, 5
        add rax, 200
        add eax, 5
        add al, 5
        add rax, [rbx]
        add [rax], rbx
        add rax, [rbx+rcx*4+16]
        sub dword [r12+8], 5
        xor eax, eax
        cmp byte [rsi], 0
        test rax, rbx
        test al, 5
        inc rax
        inc eax
        inc byte [rbx]
        dec r13
        push rbp
        push 5
        push 1000
        pop rbp
        lea rsi, [rbx+8]
        mov qword [rbp-8], 1234
        cmp rax, 0x7fffffff
        cmp rax, -1
        movzx eax, byte [rdi]
        movsxd rax, ebx
        shl rax, 3
        shl rax, 1
        shr rax, cl
        imul rax, rbx
        imul rax, rbx, 5
        neg rax
        not byte [rdi]
        mul rbx
        div qword [rbx]
        syscall
        ret
        leave
        nop
        cdq
        cqo
        sete al
        setne byte [rdi]
    ",
        "4889d8b805000000b805000000b00548b889674523010000004801d84883c005\
         4805c800000083c00504054803034801184803448b1041836c24080531c080\
         3e004885d8a80548ffc0ffc0fe0349ffcd556a0568e80300005d488d730848\
         c745f8d2040000483dffffff7f4883f8ff0fb6074863c348c1e00348d1e048\
         d3e8480fafc3486bc30548f7d8f61748f7e348f7330f05c3c9909948990f94\
         c00f9507",
    );
}

#[test]
fn branch_relaxation_bytes() {
    // Same as above but compared programmatically against nasm's known
    // output shape: two long jmps, one long jnz, then the tail.
    let bytes = text_bytes(
        r"
        bits 64
_start:
        jmp far_end
        times 200 nop
far_end:
        jnz near_target
        times 200 nop
near_target:
        mov rax, 0x123456789abcdef
        lea rbx, [rel _start]
        mov r8, [r15]
    ",
    );
    assert_eq!(&bytes[..5], &[0xe9, 0xc8, 0, 0, 0]);
    // long jnz right after the 200 nops: 0f 85 + rel32
    let j = &bytes[205..211];
    assert_eq!(&j[..2], &[0x0f, 0x85]);
    assert_eq!(
        &bytes[411..],
        &[
            0x48, 0xb8, 0xef, 0xcd, 0xab, 0x89, 0x67, 0x45, 0x23, 0x01, // mov rax, imm64
            0x48, 0x8d, 0x1d, 0x54, 0xfe, 0xff, 0xff, // lea rbx, [rel _start]
            0x4d, 0x8b, 0x07, // mov r8, [r15]: REX.WRB
        ]
    );
}

#[test]
fn short_vs_long_jmp_choice() {
    // A backward branch within rel8 stays short.
    let bytes = text_bytes(
        r"
        bits 64
start:  nop
        dec rax
        jnz start
        jmp start
    ",
    );
    assert_eq!(bytes, vec![0x90, 0x48, 0xff, 0xc8, 0x75, 0xfa, 0xeb, 0xf8]);
}

#[test]
fn local_labels() {
    let bytes = text_bytes(
        r"
        bits 64
func:
        jne .done
        nop
.done:
        ret
    ",
    );
    // jne .done (+3), nop, ret
    assert_eq!(bytes, vec![0x75, 0x01, 0x90, 0xc3]);
}

#[test]
fn data_directives() {
    let stmts = glasm::parse::parse_module(
        r"
        section .data
msg:    db 'hi', 10, 0
tbl:    dw 0x1234, 5
        dd 0xdeadbeef
        dq 7
    ",
    )
    .expect("parse");
    let module = glasm::assemble::assemble(&stmts).expect("assemble");
    let data = &module.sections.iter().find(|s| s.name == ".data").unwrap().data;
    assert_eq!(
        data,
        &[b'h', b'i', 10, 0, 0x34, 0x12, 5, 0, 0xef, 0xbe, 0xad, 0xde, 7, 0, 0, 0, 0, 0, 0, 0]
    );
}

#[test]
fn times_repeats() {
    let bytes = text_bytes("bits 64\ntimes 4 nop\ntimes 3 db 7\n");
    assert_eq!(bytes, vec![0x90; 4].into_iter().chain([7, 7, 7]).collect::<Vec<u8>>());
}

